    T = [[INF] * (max_balance + 1) for _ in range(max_balance + 1)]
    for p in range(max_balance + 1):
        if dp[0][p] == INF:
            continue
    # We need to recompute transitions per starting balance.
    # For each starting balance s, run DP over one block.
    for s in range(max_balance + 1):
        # dp_block[pos][bal]
