                        dpi1[bal - 1] = cur + bi
        for q in range(max_balance + 1):
            T[s][q] = dp_block[n][q]

    blocks = m // n

    # We need minimal cost to go from balance 0 to balance 0 after 'blocks' applications of T.
    # This is a shortest path problem in layered graph, but blocks up to 5e5 (since n>=1, m<=1e7).
    # Use DP over blocks: dp_bal[bal] = minimal cost after current number of blocks.
    dp_bal = [INF] * (max_balance + 1)
