                cost = Ts[q]
                if cost == INF:
                    continue
                val = cur + cost
                if val < new[q]:
                    new[q] = val
        dp_bal = new

    # There is no remainder positions since m is multiple of n? Not guaranteed.
    # m may not be multiple of n; handle remainder separately.
    rem = m % n
    if rem > 0:
        # DP for remainder positions with costs a[i], b[i] for i=0..rem-1
        dp_rem = [[INF] * (max_balance + 1) for _ in range(rem + 1)]
