import sys

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2 + n]))
    b = list(map(int, data[2 + n:2 + 2 * n]))

    # Precompute DP for one block of length n
    # dp[pos][balance] = minimal cost to process positions [0..pos-1] with given balance
    INF = 10 ** 18
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for pos in range(n):
        for bal in range(n + 1):
            cur = dp[pos][bal]
            if cur == INF:
                continue
            # open bracket
            if bal + 1 <= n:
                cost = cur + a[pos]
                if cost < dp[pos + 1][bal + 1]:
                    dp[pos + 1][bal + 1] = cost
            # close bracket
            if bal > 0:
                cost = cur + b[pos]
                if cost < dp[pos + 1][bal - 1]:
                    dp[pos + 1][bal - 1] = cost

    # Transition matrix T for one block: T[i][j] = minimal cost to go from balance i to j
    T = [[INF] * (n + 1) for _ in range(n + 1)]
    for start in range(n + 1):
        if dp[0][start] != INF:
            # We need to recompute from given start balance.
            # But dp was computed only from balance 0.
            # Instead, we simulate transitions using the same logic:
            # For each start balance, run DP over one block.
            # However, we can reuse the transitions since costs depend only on position.
            # We'll do a small DP per start balance (n is <=20, so n+1 states, n steps).
            local = [INF] * (n + 1)
            local[start] = 0
            for pos in range(n):
                nxt = [INF] * (n + 1)
                for bal in range(n + 1):
                    cur = local[bal]
                    if cur == INF:
                        continue
                    if bal + 1 <= n:
                        cost = cur + a[pos]
                        if cost < nxt[bal + 1]:
                            nxt[bal + 1] = cost
                    if bal > 0:
                        cost = cur + b[pos]
                        if cost < nxt[bal - 1]:
                            nxt[bal - 1] = cost
                local = nxt
            T[start] = local

    # Min-plus matrix multiplication
    def mat_mul(A, B):
        size = n + 1
        C = [[INF] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k] == INF:
                    continue
                aik = A[i][k]
                rowB = B[k]
                for j in range(size):
                    val = aik + rowB[j]
                    if val < C[i][j]:
                        C[i][j] = val
        return C

    # Fast exponentiation of T to power m_blocks (where m_blocks = m // n)
    m_blocks = m // n
    # Identity matrix for min-plus: 0 on diagonal, INF elsewhere
    size = n + 1
    R = [[INF] * size for _ in range(size)]
    for i in range(size):
        R[i][i] = 0
    P = T

    while m_blocks > 0:
        if m_blocks & 1:
            R = mat_mul(R, P)
        P = mat_mul(P, P)
        m_blocks >>= 1

    # We start with balance 0 and must end with balance 0
    ans = R[0][0]
    print(ans)

if __name__ == "__main__":
    main()
